EXTRA = {"HANOVER": (37.765, -77.37), "WINDMILL": (37.280, -77.068), "WEY_PT": (37.290, -77.066), "VICKSBURG": PL["VICKSBURG"], "MILLIKENS": (32.43, -91.08),
         "JACKSON": PL["JACKSON"], "PORT GIBSON": (31.96, -90.98), "DIMM_C": (37.237, -77.356)}
def js():
    out = {}
    for key, m in (("ric", "richmond"), ("jam", "jamesriver"), ("pet", "petersburg"), ("mis", "mississippi"), ("ten", "tennessee")):
        P = proj(m if os.path.exists(f"{ROOT}/assets/{m}_hd_lift.json") else PREV[m]); r = lambda q: [round(P(*q)[0], 1), round(P(*q)[1], 1)]
        d = {k.replace(" ", "_").replace("'", ""): r(v) for k, v in {**PL, **EXTRA}.items()}
        d.update({k: [r(q) for q in v] for k, v in LINES.items()})
        out[key] = d
    def J(m):
        b = m if os.path.exists(f"{ROOT}/assets/{m}_hd_lift.json") else PREV[m]; return json.load(open(f"{ROOT}/assets/{b}.json" if not os.path.exists(f"{ROOT}/assets/{b}_hd_lift.json") else f"{ROOT}/assets/{b}_hd_lift.json"))
    a, p = J("richmond"), J("petersburg"); k = 2 ** (p["zoom"] - a["zoom"])
    out["box_ric_in_pet"] = [k * a["origin_world_px"][0] - p["origin_world_px"][0], k * a["origin_world_px"][1] - p["origin_world_px"][1], 2880 * k, 1620 * k]
    return "const GEO = " + json.dumps(out, separators=(",", ":")) + ";\n"
if __name__ == "__main__":
    print(js()[:400])
